"""
    Maximize how much each dollar reduces percent diff from level salary. Higher scores get raise dollars first
    :param current_salary:
    :param level_salary:
    :return:
    """
def _calculate_score_for_underpaid(current_salary: Any, level_salary: Any) -> object {
    assert (current_salary <= level_salary);
    absolute_diff = current_salary - level_salary;
    percent_diff = current_salary / level_salary;
    if (absolute_diff != 0) {
        marginal_percentage = percent_diff / absolute_diff;
    } else {
        marginal_percentage = -1.0;
    }
    return marginal_percentage;
}

test_blocks:
test "t0" {
    assert (_calculate_score_for_underpaid(50000, 50000) == -1.0);;
}

test "t1" {
    assert (_calculate_score_for_underpaid(1, 1) == -1.0);;
}

test "t2" {
    assert (_calculate_score_for_underpaid(123, 123) == -1.0);;
}

test "t3" {
    assert (_calculate_score_for_underpaid(2, 2) == -1);;
}

test "t4" {
    assert (_calculate_score_for_underpaid(0, 20) == 0);;
}

test "t5" {
    assert (_calculate_score_for_underpaid(100, 100) == -1.0);;
}

test "t6" {
    assert (
        _calculate_score_for_underpaid(100000, 100000)
        == _calculate_score_for_underpaid(100000, 100000)
    );;
}

test "t7" {
